using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
using System.Threading;
using System.Threading.Tasks;
using System.Drawing;
using System.Windows.Forms;
namespace MoreSpace {
class DuplicateGroup {public string Hash;public List<Entry> Files=new List<Entry>();}
static class DuplicateScanner {
 [StructLayout(LayoutKind.Sequential)]struct FileIdentity {public uint Attributes;public System.Runtime.InteropServices.ComTypes.FILETIME Creation,Access,Write;public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(SafeFileHandle handle,out FileIdentity info);
 internal static string Hash(Entry entry,CancellationToken token,out string identity){var attributes=File.GetAttributes(entry.Path);if(!Engine.NoLinks(entry.Path)||(attributes&FileAttributes.Offline)!=0||((int)attributes&0x440000)!=0)throw new IOException("Link ou conteúdo somente na nuvem ignorado.");using(var stream=new FileStream(entry.Path,FileMode.Open,FileAccess.Read,FileShare.Read)){FileIdentity info;if(!GetFileInformationByHandle(stream.SafeFileHandle,out info))throw new IOException("Identidade do arquivo indisponível.");identity=info.Volume+":"+info.IndexHigh+":"+info.IndexLow;using(var hash=SHA256.Create()){var buffer=new byte[1024*1024];int count;while((count=stream.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();hash.TransformBlock(buffer,0,count,null,0);}hash.TransformFinalBlock(new byte[0],0,0);var current=new FileInfo(entry.Path);if(current.Length!=entry.Size||current.LastWriteTimeUtc!=entry.Modified)throw new IOException("Arquivo alterado durante a leitura.");return BitConverter.ToString(hash.Hash).Replace("-","");}}}
 public static List<DuplicateGroup> Scan(string root,CancellationToken token,Action<string> progress,long minimum=1024*1024){if(!Engine.NoLinks(root))throw new IOException("Pasta com link não é percorrida.");var bySize=new Dictionary<long,List<Entry>>();var pending=new Stack<string>();pending.Push(root);int skipped=0;while(pending.Count>0){token.ThrowIfCancellationRequested();var path=pending.Pop();try{foreach(var info in new DirectoryInfo(path).EnumerateFileSystemInfos()){token.ThrowIfCancellationRequested();var attrs=info.Attributes;if((attrs&(FileAttributes.ReparsePoint|FileAttributes.Offline))!=0||(((int)attrs)&0x440000)!=0){skipped++;continue;}if(info is DirectoryInfo){if(new[]{"node_modules",".git",".ssh",".gnupg"}.Contains(info.Name,StringComparer.OrdinalIgnoreCase))continue;pending.Push(info.FullName);}else{var f=(FileInfo)info;if(f.Length<minimum)continue;List<Entry> list;if(!bySize.TryGetValue(f.Length,out list))bySize[f.Length]=list=new List<Entry>();list.Add(new Entry{Path=f.FullName,Size=f.Length,Modified=f.LastWriteTimeUtc});}}}catch(IOException){skipped++;}catch(UnauthorizedAccessException){skipped++;}}
  var groups=new Dictionary<string,DuplicateGroup>();var identities=new HashSet<string>();int done=0;foreach(var list in bySize.Values.Where(v=>v.Count>1))foreach(var entry in list){token.ThrowIfCancellationRequested();try{string identity;var hash=Hash(entry,token,out identity);if(!identities.Add(identity))continue;DuplicateGroup group;if(!groups.TryGetValue(hash,out group))groups[hash]=group=new DuplicateGroup{Hash=hash};group.Files.Add(entry);}catch(IOException){skipped++;}catch(UnauthorizedAccessException){skipped++;}done++;if(done%10==0)progress(done+" arquivos comparados • "+skipped+" ignorados");}return groups.Values.Where(g=>g.Files.Count>1).OrderByDescending(g=>g.Files[0].Size*(g.Files.Count-1)).ToList();}
 public static void Revalidate(DuplicateGroup group,Entry candidate){var keeper=group.Files[0];if(candidate.Path==keeper.Path)throw new IOException("A cópia preservada não pode ser removida.");string id1,id2;ChartFileRules.Validate(candidate,Path.GetDirectoryName(candidate.Path));if(Hash(keeper,CancellationToken.None,out id1)!=group.Hash||Hash(candidate,CancellationToken.None,out id2)!=group.Hash||id1==id2)throw new IOException("Cópia preservada ou conteúdo mudou. Analise novamente.");}
}
partial class MainWindow {
 ListView duplicates=new SmoothListView();List<DuplicateGroup> duplicateGroups=new List<DuplicateGroup>();Label duplicateNote=new Label();Button duplicateScan,duplicateRemove;
 void SetupDuplicates(){var page=Page("Duplicados","Escolha uma pasta. Compara arquivos locais a partir de 1 MB por tamanho e SHA-256 completo. Links, arquivos só na nuvem, .git e node_modules são ignorados. Uma cópia fica protegida.");var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};duplicateScan=Btn("Escolher pasta e comparar",async delegate{if(busy)return;using(var d=new FolderBrowserDialog()){if(d.ShowDialog(this)!=DialogResult.OK)return;Busy(true);cts=new CancellationTokenSource();duplicateScan.Enabled=duplicateRemove.Enabled=false;try{var progress=new Progress<string>(text=>duplicateNote.Text=text);duplicateGroups=await Task.Run(()=>DuplicateScanner.Scan(d.SelectedPath,cts.Token,text=>((IProgress<string>)progress).Report(text)));RenderDuplicates();}catch(OperationCanceledException){duplicateNote.Text="Comparação cancelada; resultado anterior preservado.";}catch(Exception ex){MessageBox.Show(this,ex.Message);}finally{cts.Dispose();cts=null;Busy(false);duplicateScan.Enabled=duplicateRemove.Enabled=true;}}});bar.Controls.Add(duplicateScan);duplicateRemove=Btn("Revisar cópias marcadas…",async delegate{await RemoveDuplicates();});bar.Controls.Add(duplicateRemove);bar.Controls.Add(Btn("Cancelar",delegate{if(cts!=null)cts.Cancel();}));page.Controls.Add(bar,0,1);duplicates.Dock=DockStyle.Fill;duplicates.View=View.Details;duplicates.CheckBoxes=true;duplicates.FullRowSelect=true;duplicates.Columns.Add("Grupo / cópia",155);duplicates.Columns.Add("Tamanho",110);duplicates.Columns.Add("Arquivo",220);duplicates.Columns.Add("Caminho",500);duplicates.ItemCheck+=delegate(object sender,ItemCheckEventArgs e){var item=duplicates.Items[e.Index];if(busy||item.Text.EndsWith("Manter"))e.NewValue=e.CurrentValue;};page.Controls.Add(duplicates,0,2);duplicateNote.Dock=DockStyle.Fill;duplicateNote.Text="Nada vem selecionado. A cópia indicada como Manter nunca entra na remoção.";page.Controls.Add(duplicateNote,0,3);}
 void RenderDuplicates(){duplicates.Items.Clear();int group=0;foreach(var g in duplicateGroups){group++;for(int i=0;i<g.Files.Count;i++){var f=g.Files[i];var row=new ListViewItem(new[]{group+" • "+(i==0?"Manter":"Cópia"),Engine.Bytes(f.Size),Path.GetFileName(f.Path),f.Path});row.Tag=Tuple.Create(g,f);if(i==0)row.ForeColor=Color.Gray;duplicates.Items.Add(row);}}duplicateNote.Text=duplicateGroups.Count+" grupos • "+Engine.Bytes(duplicateGroups.Sum(g=>g.Files[0].Size*(g.Files.Count-1)))+" de cópias lógicas • revise antes de remover.";}
 async Task RemoveDuplicates(){if(busy)return;var selected=duplicates.CheckedItems.Cast<ListViewItem>().Select(i=>(Tuple<DuplicateGroup,Entry>)i.Tag).ToList();if(selected.Count==0)return;using(var dialog=new ChartFileDialog(null,selected.Select(x=>x.Item2).ToList(),true)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var approved=dialog.Selection.Select(e=>e.Path).ToHashSetCompat();bool permanent=dialog.Permanent;Busy(true);cancel.Enabled=false;var before=SavingsStore.Snapshot();long bytes=0;int count=0;var removed=new List<Tuple<DuplicateGroup,Entry>>();try{foreach(var pair in selected.Where(p=>approved.Contains(p.Item2.Path))){try{await Task.Run(()=>{DuplicateScanner.Revalidate(pair.Item1,pair.Item2);FileRemoval.Delete(pair.Item2.Path,permanent);});count++;bytes+=pair.Item2.Size;removed.Add(pair);Log("CÓPIA REMOVIDA "+pair.Item2.Path);}catch(Exception ex){Log("CÓPIA PRESERVADA "+pair.Item2.Path+": "+ex.Message);}}foreach(var pair in removed)pair.Item1.Files.Remove(pair.Item2);duplicateGroups=duplicateGroups.Where(g=>g.Files.Count>1).ToList();if(count>0)RecordSavings(permanent?"Duplicados":"Via Lixeira (cópias)",count,permanent?(long?)bytes:null,before);RenderDuplicates();MessageBox.Show(this,count+" cópias processadas. A cópia de referência foi preservada. Consulte Atividade para falhas.");}finally{Busy(false);}}}
}
static class Compatibility {public static HashSet<string> ToHashSetCompat(this IEnumerable<string> source){return new HashSet<string>(source,StringComparer.OrdinalIgnoreCase);}}
}
